CREATE TABLE [dbo].[conversation](	  [conversationId] INT NOT NULL IDENTITY(1,1)	, [inboundId] SMALLINT NOT NULL	, [info] VARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [isInbox] BIT NOT NULL	, [isFinished] BIT NOT NULL	, [mailClient] VARCHAR(60) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [mailInbound] VARCHAR(60) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [meanContactTypeId] SMALLINT NOT NULL)